using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RepairWithActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Hevelius/RepairWithActionCustomDescription", order = 0)]
public class RepairWithActionCustomDescription : RepairCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		RepairWithActionAction repairWithActionAction = battleAction as RepairWithActionAction;
		string text = "";
		string text2 = "";
		string text3 = "";
		if (repairWithActionAction.RestorePreviousEffects)
		{
			text3 = "\n" + base.localizationManager.GetLocalizedString("RepairRestorePreviousEffects");
		}
		text2 = ((!repairWithActionAction.AllSentinels) ? GetRepairASentinelLocalizedString() : GetRepairAllSentinelsLocalizedString());
		return text2 + "\n" + Smart.Format(arg0: (!repairWithActionAction.UseDirectDescription) ? repairWithActionAction.BattleAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).LowercaseFirst() : Smart.Format(base.localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.GetActionID()), GetFinalAmountWithoutEquation(amountModified)), format: GetIfYouDoLocalizedString()) + text3;
	}
}
